function T=Run_InternalGapLinearityDiagnostic()
%RUN_INTERNALGAPLINEARITYDIAGNOSTIC Quantify VP first-order model mismatch.
root=fileparts(mfilename('fullpath'));mainDir=fileparts(root);addpath(mainDir,'-begin');addpath(fullfile(mainDir,'local_func'),'-begin');
ctx=load_inv_log_2_project_context(mainDir);tr=load_fixed_trust_domain(mainDir);lib=make_fixed_trust_template_library(ctx.gapList,ctx.xCell,ctx.yCell,NaN,ctx.cfgAna.xGridN,get_inv_log_2_model_def(),tr);base=make_inv_log_2_demo_case(ctx,.2);cfg=base.cfgCase;cfg.RPM_low=min(cfg.RPM_high,300);cfg.NumRevs_low=20;cfg.NumRevs_high=8;cfg.route30ForwardModel="low_increment";cfg.f_true=[700 1200];cfg.A_true=[.25 .15];cfg.phi_true=[pi/4 -pi/3];pairs=[.5 .4;.5 .6;.5 .8;.8 .5];uLow=unique(pairs(:,1),'stable');r=repmat(struct('g_low_mm',NaN,'g_high_mm',NaN,'delta_gap_mm',NaN,'linearization_rmse_V',NaN,'waveform_rms_V',NaN,'vibration_rms_V',NaN,'noise_std_15db_V',NaN,'noise_std_5db_V',NaN,'effective_vibration_snr_15db',NaN,'effective_vibration_snr_5db',NaN,'relative_linearization_pct',NaN,'equivalent_noise_ratio_15db',NaN,'equivalent_noise_ratio_5db',NaN,'max_abs_slope_V_per_mm',NaN),size(pairs,1),1);
for il=1:numel(uLow),gLow=uLow(il);low=simulate_low_speed_template(@(z)eval_gap_template(lib,gLow,z),cfg,lib.domain,15,951000+il);C=calibrate_inv_log_2_low_speed(low,lib,cfg);idx=find(pairs(:,1)==gLow).';for ip=idx,gHigh=pairs(ip,2);data=simulate_highspeed_from_low_increment(C.templateModel,gHigh-C.pathCal.g0,cfg,Inf,'snr_db',1);clean=data;clean.V_cap=clean.V_clean;map=map_highspeed_to_space(clean,cfg.alpha_k,cfg.R_tip,lib.domain,.02);u=zeros(size(map.t_v));for q=1:numel(cfg.A_true),u=u+cfg.A_true(q)*sin(2*pi*cfg.f_true(q)*map.t_v+cfg.phi_true(q));end;F0=eval_gap_template(C.templateModel,gHigh,map.x_v);Fx=eval_gap_derivative(C.templateModel,gHigh,map.x_v);Vlin=F0-Fx.*u;e=map.V_a-Vlin;baseV=min(map.V_a);waveRms=rms(map.V_a-baseV);vibRms=rms(map.V_a-F0);baseline=min(data.V_clean);active=abs(data.V_clean-baseline)>.02*data.signal_range;activeRms=rms(data.V_clean(active)-baseline);n15=activeRms/10^(15/20);n5=activeRms/10^(5/20);r(ip).g_low_mm=gLow;r(ip).g_high_mm=gHigh;r(ip).delta_gap_mm=gHigh-gLow;r(ip).linearization_rmse_V=rms(e);r(ip).waveform_rms_V=waveRms;r(ip).vibration_rms_V=vibRms;r(ip).noise_std_15db_V=n15;r(ip).noise_std_5db_V=n5;r(ip).effective_vibration_snr_15db=20*log10(vibRms/n15);r(ip).effective_vibration_snr_5db=20*log10(vibRms/n5);r(ip).relative_linearization_pct=100*rms(e)/waveRms;r(ip).equivalent_noise_ratio_15db=rms(e)/(waveRms/10^(15/20));r(ip).equivalent_noise_ratio_5db=rms(e)/(waveRms/10^(5/20));r(ip).max_abs_slope_V_per_mm=max(abs(Fx));end,end
T=struct2table(r);out=fullfile(root,'output','adaptive_sg_internal_gap_matrix');writetable(T,fullfile(out,'linearity_diagnostic.csv'));save(fullfile(out,'linearity_diagnostic.mat'),'T');disp(T);
end
